        $('#form-tambah-data').on('submit', function(e) {
            e.preventDefault();
            var formData = new FormData(this);
            var form = this;
            $.ajax({
                type: $(this).attr('method'),
                url: $(this).attr('action'),
                headers: {
                    'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
                },
                data: new FormData(this),
                processData: false,
                contentType: false,
                beforeSend: function() {
                    $('#btn-simpan-data').attr('disabled', 'disabled');
                    $('#btn-simpan-data').html('<i class="fas fa-spinner fa-spin mr-1"></i> Simpan');
                },
                complete: function() {
                    $('#btn-simpan-data').removeAttr('disabled');
                    $('#btn-simpan-data').html('Simpan');
                },
                success: function(response) {
                    // console.log(response)
                    Swal
                        .fire({
                            icon: 'success',
                            title: 'Berhasil',
                            text: 'Berhasil Menambah Data',
                            showConfirmButton: false,
                            timer: 500

