	$('.myForm-1').on('submit', function (e) {
		e.preventDefault();
		var btnTxt = $('.btn-submit-1').text();
		var formData = new FormData(this);

		$.ajax({
			type: $(this).attr('method'),
			url: $(this).attr('action'),
			data: formData,
			processData: false,
			contentType: false,
			chace: false,
			beforeSend: function () {
				$('.btn-submit-1').attr('disabled', 'disabled');
				$('.btn-submit-1').html('<i class="fas fa-spinner fa-spin"></i>');
			},
			complete: function () {
				// $('.btn-submit').removeAttr('disabled');
				$('.btn-submit-1').html(btnTxt);
			},
			success: function (response) {
				console.log(response);
				let resp = JSON.parse(response);
				if (resp['status'] == 'failed') {
					swal({
						title: "Gagal",
						text: resp['pesan'],
						icon: "warning",
						// timer: 2000, //auto close 2 second
					});
					$('.btn-submit-1').removeAttr('disabled');
				}
				
				if(resp['status'] == 'success') {
					swal({
						title: "Berhasil",
						text: resp['pesan'],
						icon: "success",
						button: false,
					});
					
					$('.btn-submit-1').prop('disabled', 'disabled');

					if(resp['redirect']) {
						setTimeout(function() { 
							window.location=resp['redirect']
						}, 2200);
					}
					else{
						setTimeout(function() { 
							window.location.reload();
						}, 1200);
					}
				}
			},
			error: function (xhr, ajaxOptions, thrownError) {
				console.log(xhr.status + "\n" + xhr.responseText + "\n" + thrownError);
			}
		});
	});
</script>
